 volume:'<path d="m11 5-6 4H2v6h3l6 4Zm4 3c2 2 2 6 0 8m3-11c4 4 4 10 0 14"/>',muted:'<path d="m11 5-6 4H2v6h3l6 4Zm5 4 5 6m0-6-5 6"/>',
