function currentId(){const route=trackFromPath(state.album.tracks,location.pathname);const legacy=Number(new URLSearchParams(location.hash.slice(1)).get('track'));return legacy>=1&&legacy<=55?legacy:(route?.id||1)}
function updatePageMetadata(track){document.title=pageTitle(track);const description=pageDescription(track);document.querySelector('meta[name=description]').content=description;document.querySelector('link[rel=canonical]').href=`https://jackzebranotes.com${trackPath(track)}`;document.querySelector('meta[property="og:title"]').content=document.title;document.querySelector('meta[property="og:description"]').content=description;document.querySelector('meta[property="og:url"]').content=`https://jackzebranotes.com${trackPath(track)}`;const schema=JSON.parse($('#page-schema').textContent);schema.name=document.title;schema.url=`https://jackzebranotes.com${trackPath(track)}`;schema.about.name=track.title;schema.about.isrcCode=track.isrc;$('#page-schema').textContent=JSON.stringify(schema);$('#song-original-title').textContent=track.originalTitle||'';$('#song-original-title').hidden=!track.originalTitle;}
// Follow is the listener's preference; overlays only suspend scrolling temporarily.
const followSuspended=()=>noteIsOpen()||!!document.querySelector('dialog[open]');
function holdFollow(){window.scrollTo({top:window.scrollY,left:window.scrollX,behavior:'instant'});}
function setFollow(value){state.follow=value;$('#follow-button').setAttribute('aria-pressed',String(value));if(value)updateActive(true);else holdFollow();}
let followResumeFrame;
