$('#note-content').onclick=e=>{const b=e.target.closest('[data-note]');if(b)openNote(b.dataset.note)};
document.querySelectorAll('.language-control [data-language]').forEach(b=>b.onclick=()=>{state.language=b.dataset.language;safeSet('zebra-language',state.language);closeNotes(false);renderLyrics();updateActive(true);});
$('#follow-button').onclick=()=>setFollow(!state.follow);$('#play').onclick=togglePlay;$('#previous').onclick=()=>{if(audio.currentTime>3)audio.currentTime=0;else selectTrack(state.track.id===1?55:state.track.id-1)};$('#next').onclick=()=>selectTrack(state.track.id%55+1);$('#next-song').onclick=e=>{if(plainClick(e)){e.preventDefault();selectTrack(state.track.id%55+1);}};$('#repeat').onclick=()=>{audio.loop=!audio.loop;$('#repeat').setAttribute('aria-pressed',String(audio.loop))};
$('#seek').oninput=e=>{if(state.loadedId===state.track.id)audio.currentTime=Number(e.target.value);else{e.target.value=0;toast('Connect the audio to seek.')}};
$('#volume').oninput=e=>{audio.volume=Number(e.target.value);audio.muted=false;e.target.style.setProperty('--progress',`${audio.volume*100}%`);$('#mute').innerHTML=svg('volume');$('#mute').setAttribute('aria-label','Mute')};audio.volume=.8;$('#volume').style.setProperty('--progress','80%');
$('#mute').onclick=()=>{audio.muted=!audio.muted;$('#mute').innerHTML=svg(audio.muted?'muted':'volume');$('#mute').setAttribute('aria-label',audio.muted?'Unmute':'Mute');};
audio.addEventListener('play',()=>{syncPlay();updateActive(true);});audio.addEventListener('pause',syncPlay);audio.addEventListener('error',()=>{if(audio.getAttribute('src'))handleAudioError(new Error(audio.error?.message||'Unsupported audio'))});audio.addEventListener('ended',()=>{if(!audio.loop&&state.track.id<55)selectTrack(state.track.id+1,true);else syncPlay()});audio.addEventListener('loadedmetadata',()=>{if(Number.isFinite(audio.duration)){$('#seek').max=audio.duration;$('#duration').textContent=fmt(audio.duration);}});audio.addEventListener('timeupdate',()=>{$('#elapsed').textContent=fmt(audio.currentTime);$('#seek').setAttribute('aria-valuetext',`${fmt(audio.currentTime)} of ${fmt(audio.duration||state.track.duration)}`);$('#seek').value=audio.currentTime;$('#seek').style.setProperty('--progress',`${audio.currentTime/(audio.duration||state.track.duration)*100}%`);updateActive();});
$('#album-toggle').onclick=e=>{if(plainClick(e)){e.preventDefault();$('#track-dialog').open?closeTrackList():openTrackList();}};$('#about-button').onclick=()=>{closeTrackList(false);showDialog('#info-dialog');};$('#manage-audio').onclick=()=>{closeTrackList(false);showDialog('#connect-dialog');};$('#song-notes-toggle').onclick=e=>openNote(null,e.currentTarget);$('#note-close').onclick=()=>closeNotes();const clearNoteState=()=>{state.note=null;highlightRelated(null);resumeFollow();document.querySelectorAll('#lyrics [data-note]').forEach(b=>b.setAttribute('aria-expanded','false'));};$('#note-popover').addEventListener('toggle',e=>{if(e.newState==='closed'&&!noteIsOpen())clearNoteState();});$('#note-popover').addEventListener('close',()=>{if(!noteIsOpen())clearNoteState();});window.addEventListener('resize',positionNote);window.addEventListener('scroll',positionNote,{passive:true});
const readingGesture=target=>!followSuspended()&&!target.closest('.player, #album-panel, dialog');
window.addEventListener('wheel',e=>{if(state.follow&&e.deltaY&&readingGesture(e.target))setFollow(false);},{passive:true});
let readingTouch=null;
window.addEventListener('touchstart',e=>{readingTouch=e.touches.length===1&&readingGesture(e.target)?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null;},{passive:true});
window.addEventListener('touchmove',e=>{
 if(!state.follow||!readingTouch||e.touches.length!==1||!readingGesture(e.target))return;
 const dx=Math.abs(e.touches[0].clientX-readingTouch.x),dy=Math.abs(e.touches[0].clientY-readingTouch.y);
 if(dy>12&&dy>dx)setFollow(false);
},{passive:true});
for(const event of ['touchend','touchcancel'])window.addEventListener(event,()=>readingTouch=null,{passive:true});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.key==='Escape'){if(noteIsOpen())closeNotes();return;}if(e.target.closest('input,textarea,button,a,summary,[contenteditable]'))return;if(e.code==='Space'){e.preventDefault();togglePlay();}if(e.code==='ArrowRight'&&state.loadedId){e.preventDefault();audio.currentTime=Math.min(audio.duration,audio.currentTime+5);}if(e.code==='ArrowLeft'&&state.loadedId){e.preventDefault();audio.currentTime=Math.max(0,audio.currentTime-5);}if(['ArrowDown','ArrowUp','PageDown','PageUp','Home','End'].includes(e.code)&&readingGesture(e.target))setFollow(false);});
$('#drop-area').ondragover=e=>{e.preventDefault();$('#drop-area').classList.add('drag-over')};$('#drop-area').ondragleave=()=>$('#drop-area').classList.remove('drag-over');$('#drop-area').ondrop=e=>{e.preventDefault();$('#drop-area').classList.remove('drag-over');importFiles([...e.dataTransfer.files]);};
window.addEventListener('popstate',()=>{if(state.album)selectTrack(currentId(),false,false)});
window.addEventListener('hashchange',()=>{if(state.album&&location.hash.startsWith('#track='))selectTrack(currentId(),false,'replace')});
async function init(){try{const r=await fetch('/album.json',{cache:'no-cache'});if(!r.ok)throw Error('Album could not load.');state.album=await r.json();selectTrack(currentId(),false,'replace');document.documentElement.classList.add('enhanced');if(['localhost','127.0.0.1'].includes(location.hostname)&&!new URLSearchParams(location.search).has('manual')){try{const local=await fetch('/__local/manifest');if(local.ok){const entries=await local.json();for(const t of entries.tracks)state.files.set(t.id,{url:`/__local/audio/${t.id}`,format:'flac'});setConnection();await loadAudio(false);}}catch{/* Hosted readers connect their own files. */}}}catch(e){toast('Interactive controls could not load. You can still read the lyrics and notes below.');console.error(e);}}
function updateMediaMetadata(){
 if(!('mediaSession' in navigator)||!('MediaMetadata' in window)||!state.track)return;
 const t=state.track;navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:state.album.title,artwork:[{src:new URL('/assets/cover.jpg',location.href).href,type:'image/jpeg'}]});
}
function updateMediaPosition(){if(!navigator.mediaSession?.setPositionState||!Number.isFinite(audio.duration)||audio.duration<=0)return;try{navigator.mediaSession.setPositionState({duration:audio.duration,position:Math.min(audio.currentTime,audio.duration),playbackRate:audio.playbackRate});}catch{}}
if('mediaSession' in navigator){
 const actions={play:()=>loadAudio(true).catch(handleAudioError),pause:()=>audio.pause(),previoustrack:()=>$('#previous').click(),nexttrack:()=>$('#next').click(),seekbackward:d=>audio.currentTime=Math.max(0,audio.currentTime-(d.seekOffset||10)),seekforward:d=>audio.currentTime=Math.min(audio.duration||0,audio.currentTime+(d.seekOffset||10)),seekto:d=>{if(Number.isFinite(d.seekTime))audio.currentTime=d.seekTime;}};
 for(const [action,handler]of Object.entries(actions)){try{navigator.mediaSession.setActionHandler(action,handler);}catch{}}
 for(const event of ['loadedmetadata','timeupdate','seeked','ratechange'])audio.addEventListener(event,updateMediaPosition);
}
function registerAgentTools(){
 const context=document.modelContext;if(!context?.registerTool)return;
 const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_listening_state',title:'Read listening state',description:'Read the selected track, playback position, connected audio count, and lyric availability.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {track:state.track?{id:state.track.id,title:state.track.title,hasLyrics:!!state.track.lyrics.length}:null,playing:!audio.paused,seconds:audio.currentTime,connectedTracks:state.files.size}}});
 register({name:'select_listening_track',title:'Select a song',description:'Select one of the 55 tracks and show its lyrics and notes. Pauses playback; does not upload audio or start sound.',inputSchema:{type:'object',properties:{track:{type:'integer',minimum:1,maximum:55}},required:['track'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input?.track)||input.track<1||input.track>55||!state.album)throw Error('Choose a track number from 1 to 55.');selectTrack(input.track,false);return {track:state.track.id,title:state.track.title,hasLyrics:!!state.track.lyrics.length}}});
}
init().then(registerAgentTools);
